/**
 * Test flow for getCatalogVariables action
 * Demonstrates getting catalog variables
 */

import { action, Flow, wfa, trigger } from '@servicenow/sdk/automation'

export const testGetCatalogVariables = Flow(
    {
        $id: Now.ID['test_get_catalog_variables_flow'],
        name: 'Test Get Catalog Variables',
        description: 'Tests the getCatalogVariables core action',
    },
    wfa.trigger(
        trigger.record.created,
        { $id: Now.ID['test_get_catalog_variables_trigger'] },
        {
            table: 'sc_req_item',
            condition: 'active=true',
            run_flow_in: 'background',
        }
    ),
    (params) => {
        wfa.action(
            action.core.getCatalogVariables,
            { $id: Now.ID['test_get_catalog_variables_action'] },
            {
                requested_item: params.trigger.current.sys_id,
                template_catalog_item: 'sample_catalog_item_sys_id',
            }
        )

        wfa.action(
            action.core.log,
            { $id: Now.ID['test_get_catalog_variables_log'] },
            {
                log_level: 'info',
                log_message: `getCatalogVariables outputs: (no outputs)`,
            }
        )
    }
)
